def main() -> None:
    root = Path.cwd()
    data = json.loads(lzma.decompress(base64.b85decode(PAYLOAD_B85)).decode("utf-8"))

    for rel, content in data["full_files"].items():
        p = root / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(content, encoding="utf-8")
        print(f"[write] {rel} ({len(content)} chars)")

    for item in data["replacements"]:
        p = root / item["path"]
        text = p.read_text(encoding="utf-8")
        old = item["old"]
        new = item["new"]
        if new in text:
            print(f"[skip-already-applied] {item['path']}")
            continue
        if old not in text:
            raise RuntimeError(f"Anchor not found in {item['path']}:\n{old[:200]}")
        count = text.count(old)
        if count != 1:
            raise RuntimeError(f"Expected 1 occurrence in {item['path']}, got {count}")
        p.write_text(text.replace(old, new, 1), encoding="utf-8")
        print(f"[patch] {item['path']}")

    print("All macOS HiDPI 2K + ScreenCaptureKit NV12 + Steady-FPS changes applied successfully.")


if __name__ == "__main__":
    main()
